const vo = $input.first().json.output;
const d = (s) => (s ? new Date(s + 'T00:00:00Z') : null);
const tage = (a, b) => (a && b ? Math.round((b - a) / 86400000) : null);
const aus = d(vo.ausstellungsdatum);
const pruef = d(vo.pruefdatum);
const beginn = d(vo.geplanter_beginn) || pruef;
const letzte = d(vo.letzte_behandlung);
const grenze = vo.dringlich ? 14 : 28;
const bereitsBegonnen = !!letzte;
const tageBisBeginn = bereitsBegonnen ? null : tage(aus, beginn);
const unterbrechung = letzte ? tage(letzte, beginn) : null;
const hm = Array.isArray(vo.heilmittel) ? vo.heilmittel : [];
// ICD-10-Bereich -> Körperregion (Kapitelstruktur ICD-10-GM, nur Muskel-Skelett; sonst null = LLM prüft mit RAG)
const icdRegion = (code) => {
  if (!code) return null;
  const m = String(code).toUpperCase().match(/^([A-Z])(\d{2})/);
  if (!m) return null;
  const k = m[1], n = Number(m[2]);
  if (k === 'M' && n >= 40 && n <= 54) return 'WS';                 // Krankheiten der Wirbelsäule und des Rückens
  if (k === 'S' && [12, 13, 22, 23, 32, 33].includes(n)) return 'WS'; // Verletzungen Hals-, Brust-, Lendenwirbelsäule
  if (k === 'M' && n >= 15 && n <= 25) return 'EX';                 // Arthrosen und sonstige Gelenkkrankheiten
  if (k === 'M' && [75, 76, 77].includes(n)) return 'EX';           // Schulter, untere Extremität, Enthesopathien
  if (k === 'S' && n >= 40 && n <= 99) return 'EX';                 // Verletzungen Schulter bis Fuß
  return null;
};
const region = icdRegion(vo.icd10);
const dg = vo.diagnosegruppe ? String(vo.diagnosegruppe).toUpperCase().trim() : null;
const ist_marker = (wert) => /^\[[^\]]+\]$/.test(String(wert ?? '').trim());
// Marker = redigiert: Feld ausgefüllt, Format nicht prüfbar (null), nicht fehlerhaft (false).
const formatOk = (wert) => (vorhanden(wert) && !ist_marker(wert) ? /^\d{9}$/.test(String(wert).trim()) : null);
const vorhanden = (wert) => wert !== null && wert !== undefined && String(wert).trim() !== '';
// Pflichtangaben deterministisch aus dem Original – nach der PII-Redaktion stehen bei LANR/BSNR nur Marker.
const pflichtangaben = {
  kostentraeger: vorhanden(vo.patient?.krankenkasse) || vorhanden(vo.kostentraeger),
  lanr: vorhanden(vo.lanr),
  bsnr: vorhanden(vo.bsnr),
  ausstellungsdatum: vorhanden(vo.ausstellungsdatum),
  unterschrift: vo.unterschrift === true,
  icd10: vorhanden(vo.icd10) || (Array.isArray(vo.diagnosen) && vo.diagnosen.length > 0),
  diagnosegruppe: vorhanden(vo.diagnosegruppe),
  leitsymptomatik: vorhanden(vo.leitsymptomatik) || vorhanden(vo.leitsymptomatik_freitext),
  heilmittel_mit_einheiten: hm.some((h) => Number(h.einheiten) > 0),
  frequenz: vorhanden(vo.frequenz)
};
const fakten = {
  frist_grenze_tage: grenze,
  dringlich: !!vo.dringlich,
  bereits_begonnen: bereitsBegonnen,
  tage_ausstellung_bis_beginn: tageBisBeginn,
  beginn_fristgerecht: tageBisBeginn === null ? null : tageBisBeginn <= grenze,
  tage_unterbrechung: unterbrechung,
  unterbrechung_grenze_tage: 14,
  unterbrechung_zulaessig: unterbrechung === null ? null : (unterbrechung <= 14 || !!vo.unterbrechungsgrund),
  summe_einheiten: hm.reduce((s, h) => s + (Number(h.einheiten) || 0), 0),
  anzahl_vorrangige_heilmittel: hm.filter((h) => h.art === 'vorrangig').length,
  lanr_format_ok: formatOk(vo.lanr),
  bsnr_format_ok: formatOk(vo.bsnr),
  pflichtangaben,
  icd_passende_diagnosegruppe: region,
  diagnosegruppe_passt_zu_icd: region && dg && ['WS', 'EX'].includes(dg) ? region === dg : null
};
return [{ json: { vo, fakten, diagnose_auswahl: $input.first().json.diagnose_auswahl || { hinweise: [] }, start_ms: Date.now() } }];

